EXECUTE IMMEDIATE $$
-- JSON variant of tools/sf_prepare.sql (targets old_json and new_json): the initial row stages JSON (STAGE_FILE_TYPE and
-- STAGE_FILE_SPEC NULL, as RDBMS rows do), OBJECT_NAME is <table>_part_%.json, and SCHEMA_DRIFT_CODE is copied from
-- the delta twin (2): JSON has no schema, so columns absent from the first file (all NULL there) are added later
-- instead of being dropped. Live mode can also convert the table's Parquet INITIAL_LOAD row to JSON (opt-in, below).
-- Everything else is identical.
-- 'Prepare row' Lookup: the setup DML, run as the ADF role (which holds CONTROL_DEV_RW), before 'Check pair'.
--   Test  (source_from set, table = <source_from>_PRIME_TEST): create the test INITIAL_LOAD row from the live delta
--         twin if it does not exist yet. New, inactive, separate row; nothing existing changes.
--   Live  (no source_from): the live INITIAL_LOAD row must have SQL_STATEMENT NULL, PARALLEL_STAGE_LOAD_FLAG TRUE and
--         RUN_GROUP DATA_PRIME. With p_Prepare_Live_Row = true, fix that one row (or create it if the table has
--         none); the old values are returned in OLD_VALUES (the ADF run output is the backup). Otherwise stop and
--         say exactly what would change.
--         If the table has no JSON initial row but exactly one Parquet INITIAL_LOAD row (an earlier Parquet onboarding),
--         p_Prepare_Live_Row = true converts that row in place to JSON (OBJECT_NAME <t>_part_%.json, STAGE_FILE_TYPE and
--         STAGE_FILE_SPEC NULL, SCHEMA_DRIFT_CODE from the delta twin) plus the fixes above. Its id, SOURCE_NAME and
--         SOURCE_PATH stay. OLD_VALUES holds every changed column, so the row can be put back by hand.
--   Anything else: no change; 'Check pair' reports the problem.
-- CONTROL text columns carry a collation: COLLATE(col, '') before TRIM with characters and SPLIT_PART.
-- Tokens {{...}} are replaced by tools/build_pipelines.py.
DECLARE
    v_status  VARCHAR DEFAULT 'OK';
    msg       VARCHAR DEFAULT '';
    v_action  VARCHAR DEFAULT 'NONE';
    v_table   VARCHAR DEFAULT UPPER(TRIM('@{replace(trim(string(item().table)), '''', '''''')}'));
    v_src     VARCHAR DEFAULT UPPER(TRIM('@{replace(coalesce(item()?.source_from, ''), '''', '''''')}'));
    v_path    VARCHAR;
    n_delta   NUMBER DEFAULT 0;
    n_init    NUMBER DEFAULT 0;
    n_name    NUMBER DEFAULT 0;
    n_path    NUMBER DEFAULT 0;
    v_id      NUMBER;
    v_active  BOOLEAN;
    v_needs   BOOLEAN;
    v_old     VARCHAR;
    n_dup     NUMBER DEFAULT 0;
    n_pq      NUMBER DEFAULT 0;
    res       RESULTSET;
BEGIN
    -- Cheap input checks first, so a bad parameter never leaves setup DML behind.
    IF (TRY_TO_BOOLEAN('@{replace(string(coalesce(item()?.enable_delta, pipeline().parameters.p_Enable_Delta)), '''', '''''')}') IS NULL) THEN
        v_status := 'ERROR';
        msg := 'enable_delta / p_Enable_Delta must be true or false, got @{replace(string(coalesce(item()?.enable_delta, pipeline().parameters.p_Enable_Delta)), '''', '''''')}. Nothing changed.';
    ELSEIF (@{string(pipeline().parameters.p_Rows_Per_File)} < 1000) THEN
        v_status := 'ERROR';
        msg := 'p_Rows_Per_File must be at least 1000, got @{string(pipeline().parameters.p_Rows_Per_File)}. Nothing changed.';
    ELSEIF (v_src <> '' AND v_table = v_src || '_PRIME_TEST') THEN
        -- ---------------------------------------------------------------- test target
        SELECT COUNT(*) INTO :n_name FROM EDP_DEV.CONTROL.EXTRACT_META WHERE UPPER(STAGE_TABLE_NAME) = :v_table;
        IF (n_name > 0) THEN
            v_action := 'TEST_ROW_EXISTS';
            msg := 'Test row for ' || v_table || ' already exists.';
        ELSE
            v_path := 'data_prime_test/' || LOWER(v_table) || '/';
            SELECT COUNT(*) INTO :n_delta FROM EDP_DEV.CONTROL.EXTRACT_META
            WHERE UPPER(STAGE_TABLE_NAME) = :v_src AND SOURCE_TYPE = 'TABLE';
            SELECT COUNT(*) INTO :n_path FROM EDP_DEV.CONTROL.EXTRACT_META
            WHERE LOWER(TRIM(COLLATE(SOURCE_PATH, ''), '/ ')) = LOWER(TRIM(:v_path, '/ '));
            IF (n_delta <> 1) THEN
                v_status := 'ERROR';
                msg := 'Cannot create the test row: expected 1 delta twin (SOURCE_TYPE TABLE) named ' || v_src
                    || ', found ' || n_delta || '.';
            ELSEIF (n_path > 0) THEN
                v_status := 'ERROR';
                msg := 'Cannot create the test row: SOURCE_PATH ' || v_path || ' is already used.';
            ELSE
                INSERT INTO EDP_DEV.CONTROL.EXTRACT_META
                    (SOURCE_NAME, SOURCE_TYPE, OBJECT_NAME, LOAD_TYPE, PRIMARY_KEYS, SQL_SNIPPET, RUN_GROUP,
                     LVL2_FOLDER_NAME, LANDING_SCHEMA, TARGET_SCHEMA, STAGE_TABLE_NAME, ACTIVE_FLAG, SQL_STATEMENT,
                     SOURCE_PATH, REMOVE_SOURCE_FILE_FLAG, RELOAD_SAME_FILE_FLAG, STAGE_FILE_TYPE, STAGE_FILE_SPEC,
                     SCHEMA_DRIFT_CODE, PARALLEL_STAGE_LOAD_FLAG)
                SELECT d.SOURCE_NAME || '_' || UPPER(SPLIT_PART(COLLATE(d.OBJECT_NAME, ''), '.', -1)) || '_PRIME_TEST_INITIAL_LOAD',
                       'FILE', LOWER(SPLIT_PART(COLLATE(d.OBJECT_NAME, ''), '.', -1)) || '_part_%.json', 'APPEND',
                       d.PRIMARY_KEYS, NULL, 'DATA_PRIME', d.LVL2_FOLDER_NAME || '_PRIME_TEST', d.LANDING_SCHEMA,
                       d.TARGET_SCHEMA, :v_table, FALSE, NULL, :v_path, FALSE, FALSE, NULL, NULL,
                       COALESCE(d.SCHEMA_DRIFT_CODE, 2), TRUE
                FROM EDP_DEV.CONTROL.EXTRACT_META d
                WHERE UPPER(d.STAGE_TABLE_NAME) = :v_src AND d.SOURCE_TYPE = 'TABLE'
                  AND NOT EXISTS (SELECT 1 FROM EDP_DEV.CONTROL.EXTRACT_META x WHERE UPPER(x.STAGE_TABLE_NAME) = :v_table);
                IF (SQLROWCOUNT = 0) THEN
                    v_action := 'TEST_ROW_EXISTS';
                    msg := 'Test row for ' || v_table || ' was created by another run.';
                ELSE
                    v_action := 'CREATED_TEST_ROW';
                    msg := 'Created test row ' || v_table || ' (inactive, DATA_PRIME, SOURCE_PATH ' || v_path || ').';
                END IF;
                -- Two first-time runs at once can both insert (no unique constraints): keep the lowest id.
                DELETE FROM EDP_DEV.CONTROL.EXTRACT_META
                WHERE UPPER(STAGE_TABLE_NAME) = :v_table AND SOURCE_TYPE = 'FILE' AND NOT COALESCE(ACTIVE_FLAG, FALSE)
                  AND ENDSWITH(UPPER(SOURCE_NAME), '_PRIME_TEST_INITIAL_LOAD')
                  AND EXTRACT_META_ID > (SELECT MIN(EXTRACT_META_ID) FROM EDP_DEV.CONTROL.EXTRACT_META
                                         WHERE UPPER(STAGE_TABLE_NAME) = :v_table);
                n_dup := SQLROWCOUNT;
                IF (n_dup > 0) THEN
                    msg := msg || ' Removed ' || n_dup || ' duplicate(s) from a concurrent run.';
                END IF;
            END IF;
        END IF;
    ELSEIF (v_src = '') THEN
        -- ---------------------------------------------------------------- live table
        SELECT COUNT(*), MAX(EXTRACT_META_ID) INTO :n_init, :v_id FROM EDP_DEV.CONTROL.EXTRACT_META
        WHERE UPPER(STAGE_TABLE_NAME) = :v_table AND SOURCE_TYPE = 'FILE' AND STAGE_FILE_TYPE IS NULL
          AND ENDSWITH(UPPER(SOURCE_NAME), 'INITIAL_LOAD');
        IF (n_init = 1) THEN
            SELECT TO_VARCHAR(OBJECT_CONSTRUCT_KEEP_NULL('EXTRACT_META_ID', EXTRACT_META_ID, 'SQL_STATEMENT', SQL_STATEMENT,
                                              'PARALLEL_STAGE_LOAD_FLAG', PARALLEL_STAGE_LOAD_FLAG,
                                              'RUN_GROUP', RUN_GROUP, 'ACTIVE_FLAG', ACTIVE_FLAG)),
                   COALESCE(ACTIVE_FLAG, FALSE),
                   (SQL_STATEMENT IS NOT NULL OR NOT COALESCE(PARALLEL_STAGE_LOAD_FLAG, FALSE)
                    OR UPPER(COALESCE(COLLATE(RUN_GROUP, ''), '')) <> 'DATA_PRIME')
            INTO :v_old, :v_active, :v_needs
            FROM EDP_DEV.CONTROL.EXTRACT_META WHERE EXTRACT_META_ID = :v_id;
            IF (NOT v_needs) THEN
                v_action := 'LIVE_ROW_READY';
                msg := 'Initial row ' || v_id || ' is ready.';
            ELSEIF (NOT @{pipeline().parameters.p_Prepare_Live_Row}) THEN
                v_status := 'ERROR';
                v_action := 'LIVE_ROW_NEEDS_PREPARE';
                msg := 'Initial row ' || v_id || ' needs SQL_STATEMENT NULL, PARALLEL_STAGE_LOAD_FLAG TRUE and RUN_GROUP '
                    || 'DATA_PRIME (now ' || v_old || '). Nothing changed. Re-run with p_Prepare_Live_Row = true '
                    || 'to apply; the old values are recorded in this output.';
            ELSEIF (v_active) THEN
                v_status := 'ERROR';
                msg := 'Initial row ' || v_id || ' is ACTIVE (a prime is running, or one was cancelled); not changed.';
            ELSE
                UPDATE EDP_DEV.CONTROL.EXTRACT_META
                SET SQL_STATEMENT = NULL, PARALLEL_STAGE_LOAD_FLAG = TRUE, RUN_GROUP = 'DATA_PRIME'
                WHERE EXTRACT_META_ID = :v_id AND COALESCE(ACTIVE_FLAG, FALSE) = FALSE;
                IF (SQLROWCOUNT = 0) THEN
                    v_status := 'ERROR';
                    msg := 'Initial row ' || v_id || ' became ACTIVE before it could be prepared; not changed.';
                ELSE
                    v_action := 'LIVE_ROW_PREPARED';
                    msg := 'Prepared initial row ' || v_id || '. Old values: ' || v_old || '.';
                END IF;
            END IF;
        ELSEIF (n_init = 0) THEN
            SELECT COUNT(*) INTO :n_delta FROM EDP_DEV.CONTROL.EXTRACT_META
            WHERE UPPER(STAGE_TABLE_NAME) = :v_table AND SOURCE_TYPE = 'TABLE';
            SELECT COUNT(*), MAX(EXTRACT_META_ID) INTO :n_pq, :v_id FROM EDP_DEV.CONTROL.EXTRACT_META
            WHERE UPPER(STAGE_TABLE_NAME) = :v_table AND SOURCE_TYPE = 'FILE' AND UPPER(STAGE_FILE_TYPE) = 'PARQUET'
              AND ENDSWITH(UPPER(SOURCE_NAME), 'INITIAL_LOAD');
            v_path := 'data_prime/' || LOWER(v_table) || '/';
            SELECT COUNT(*) INTO :n_path FROM EDP_DEV.CONTROL.EXTRACT_META
            WHERE LOWER(TRIM(COLLATE(SOURCE_PATH, ''), '/ ')) = LOWER(TRIM(:v_path, '/ '));
            IF (n_pq = 1) THEN
                -- Parquet INITIAL_LOAD row from an earlier onboarding: convert it in place (opt-in).
                SELECT TO_VARCHAR(OBJECT_CONSTRUCT_KEEP_NULL('EXTRACT_META_ID', EXTRACT_META_ID, 'OBJECT_NAME', OBJECT_NAME,
                                                  'STAGE_FILE_TYPE', STAGE_FILE_TYPE, 'STAGE_FILE_SPEC', STAGE_FILE_SPEC,
                                                  'SCHEMA_DRIFT_CODE', SCHEMA_DRIFT_CODE, 'SQL_STATEMENT', SQL_STATEMENT,
                                                  'PARALLEL_STAGE_LOAD_FLAG', PARALLEL_STAGE_LOAD_FLAG,
                                                  'RUN_GROUP', RUN_GROUP, 'ACTIVE_FLAG', ACTIVE_FLAG)),
                       COALESCE(ACTIVE_FLAG, FALSE)
                INTO :v_old, :v_active
                FROM EDP_DEV.CONTROL.EXTRACT_META WHERE EXTRACT_META_ID = :v_id;
                IF (NOT @{pipeline().parameters.p_Prepare_Live_Row}) THEN
                    v_status := 'ERROR';
                    v_action := 'LIVE_ROW_NEEDS_CONVERT';
                    msg := 'Initial row ' || v_id || ' is a Parquet row (now ' || v_old || '). The JSON prime needs it '
                        || 'converted to JSON (OBJECT_NAME <t>_part_%.json, STAGE_FILE_TYPE/STAGE_FILE_SPEC NULL, '
                        || 'SCHEMA_DRIFT_CODE from the delta twin, SQL_STATEMENT NULL, PARALLEL_STAGE_LOAD_FLAG TRUE, '
                        || 'RUN_GROUP DATA_PRIME). Nothing changed. Re-run with p_Prepare_Live_Row = true to apply; '
                        || 'the old values are recorded in this output.';
                ELSEIF (n_delta <> 1) THEN
                    v_status := 'ERROR';
                    msg := 'Cannot convert initial row ' || v_id || ': expected 1 delta twin (SOURCE_TYPE TABLE) for '
                        || v_table || ', found ' || n_delta || '.';
                ELSEIF (v_active) THEN
                    v_status := 'ERROR';
                    msg := 'Initial row ' || v_id || ' is ACTIVE (a prime is running, or one was cancelled); not changed.';
                ELSE
                    UPDATE EDP_DEV.CONTROL.EXTRACT_META m
                    SET OBJECT_NAME = d.OBJ, STAGE_FILE_TYPE = NULL, STAGE_FILE_SPEC = NULL, SCHEMA_DRIFT_CODE = d.SDC,
                        SQL_STATEMENT = NULL, PARALLEL_STAGE_LOAD_FLAG = TRUE, RUN_GROUP = 'DATA_PRIME'
                    FROM (SELECT LOWER(SPLIT_PART(COLLATE(OBJECT_NAME, ''), '.', -1)) || '_part_%.json' AS OBJ,
                                 COALESCE(SCHEMA_DRIFT_CODE, 2) AS SDC
                          FROM EDP_DEV.CONTROL.EXTRACT_META
                          WHERE UPPER(STAGE_TABLE_NAME) = :v_table AND SOURCE_TYPE = 'TABLE') d
                    WHERE m.EXTRACT_META_ID = :v_id AND COALESCE(m.ACTIVE_FLAG, FALSE) = FALSE
                      AND UPPER(m.STAGE_FILE_TYPE) = 'PARQUET';
                    IF (SQLROWCOUNT = 0) THEN
                        v_status := 'ERROR';
                        msg := 'Initial row ' || v_id || ' changed before it could be converted; not changed.';
                    ELSE
                        v_action := 'LIVE_ROW_CONVERTED';
                        msg := 'Converted initial row ' || v_id || ' from Parquet to JSON. Old values: ' || v_old || '.';
                    END IF;
                END IF;
            ELSEIF (NOT @{pipeline().parameters.p_Prepare_Live_Row}) THEN
                v_status := 'ERROR';
                v_action := 'LIVE_ROW_MISSING';
                msg := v_table || ' has no JSON INITIAL_LOAD row. Nothing changed. Re-run with p_Prepare_Live_Row = true to '
                    || 'create it.';
            ELSEIF (n_delta <> 1) THEN
                v_status := 'ERROR';
                msg := 'Cannot create the initial row: expected 1 delta twin (SOURCE_TYPE TABLE) for ' || v_table
                    || ', found ' || n_delta || '.';
            ELSEIF (n_path > 0) THEN
                v_status := 'ERROR';
                msg := 'Cannot create the initial row: SOURCE_PATH ' || v_path || ' is already used.';
            ELSE
                INSERT INTO EDP_DEV.CONTROL.EXTRACT_META
                    (SOURCE_NAME, SOURCE_TYPE, OBJECT_NAME, LOAD_TYPE, PRIMARY_KEYS, SQL_SNIPPET, RUN_GROUP,
                     LVL2_FOLDER_NAME, LANDING_SCHEMA, TARGET_SCHEMA, STAGE_TABLE_NAME, ACTIVE_FLAG, SQL_STATEMENT,
                     SOURCE_PATH, REMOVE_SOURCE_FILE_FLAG, RELOAD_SAME_FILE_FLAG, STAGE_FILE_TYPE, STAGE_FILE_SPEC,
                     SCHEMA_DRIFT_CODE, PARALLEL_STAGE_LOAD_FLAG)
                SELECT d.SOURCE_NAME || '_' || UPPER(SPLIT_PART(COLLATE(d.OBJECT_NAME, ''), '.', -1)) || '_INITIAL_LOAD',
                       'FILE', LOWER(SPLIT_PART(COLLATE(d.OBJECT_NAME, ''), '.', -1)) || '_part_%.json', 'APPEND',
                       d.PRIMARY_KEYS, NULL, 'DATA_PRIME', d.LVL2_FOLDER_NAME, d.LANDING_SCHEMA, d.TARGET_SCHEMA,
                       d.STAGE_TABLE_NAME, FALSE, NULL, :v_path, FALSE, FALSE, NULL, NULL,
                       COALESCE(d.SCHEMA_DRIFT_CODE, 2), TRUE
                FROM EDP_DEV.CONTROL.EXTRACT_META d
                WHERE UPPER(d.STAGE_TABLE_NAME) = :v_table AND d.SOURCE_TYPE = 'TABLE'
                  AND NOT EXISTS (SELECT 1 FROM EDP_DEV.CONTROL.EXTRACT_META x
                                  WHERE UPPER(x.STAGE_TABLE_NAME) = :v_table AND x.SOURCE_TYPE = 'FILE');
                IF (SQLROWCOUNT = 0) THEN
                    v_status := 'ERROR';
                    msg := v_table || ' already has a FILE row that is not a JSON INITIAL_LOAD row (for example the Parquet '
                        || 'INITIAL_LOAD row); not created. Ask the ATILDA owners.';
                ELSE
                    v_action := 'CREATED_LIVE_ROW';
                    msg := 'Created initial row for ' || v_table || ' (inactive, DATA_PRIME, SOURCE_PATH ' || v_path || ').';
                    -- Two runs at once can both insert: keep the lowest id of the rows created here.
                    DELETE FROM EDP_DEV.CONTROL.EXTRACT_META
                    WHERE UPPER(STAGE_TABLE_NAME) = :v_table AND SOURCE_TYPE = 'FILE' AND NOT COALESCE(ACTIVE_FLAG, FALSE)
                      AND UPPER(COALESCE(COLLATE(RUN_GROUP, ''), '')) = 'DATA_PRIME'
                      AND LOWER(TRIM(COLLATE(SOURCE_PATH, ''), '/ ')) = LOWER(TRIM(:v_path, '/ '))
                      AND EXTRACT_META_ID > (SELECT MIN(EXTRACT_META_ID) FROM EDP_DEV.CONTROL.EXTRACT_META
                                             WHERE UPPER(STAGE_TABLE_NAME) = :v_table AND SOURCE_TYPE = 'FILE');
                END IF;
            END IF;
        END IF;
    END IF;
    res := (SELECT :v_status AS STATUS, :msg AS MESSAGE, :v_action AS ACTION, :v_old AS OLD_VALUES);
    RETURN TABLE(res);
END;
$$

sqlReaderQuery.value:
-- JSON variant of tools/source_query.tsql (targets old_json and new_json): raw SELECT list (delta text), one batch per
-- p_Rows_Per_File rows (each batch is one JSON file), no Parquet column-name check.
SET NOCOUNT ON;
-- Inputs. Each value enters once as a literal and is only compared or parsed, never spliced into SQL.
DECLARE @obj  nvarchar(512) = N'@{replace(activity('Check pair').output.firstRow.SOURCE_OBJECT, '''', '''''')}';    -- delta twin OBJECT_NAME, schema.table
DECLARE @wcol sysname       = N'@{replace(coalesce(item()?.window_column, ''), '''', '''''')}';   -- window column, '' = none
DECLARE @ws   nvarchar(64)  = N'@{replace(coalesce(item()?.window_start, pipeline().parameters.p_Window_Start), '''', '''''')}';     -- window start (inclusive), '' = none
DECLARE @we   nvarchar(64)  = N'@{replace(coalesce(item()?.window_end, pipeline().parameters.p_Window_End), '''', '''''')}';     -- window end (exclusive), '' = server clock for date columns
DECLARE @pcol sysname       = N'@{replace(coalesce(item()?.partition_column, ''), '''', '''''')}';   -- partition column, '' = single stream
DECLARE @n    int           = @{string(pipeline().parameters.p_Rows_Per_File)};         -- rows per batch = rows per file (p_Rows_Per_File)

DECLARE @err nvarchar(4000) = N'';
DECLARE @oid int = (SELECT o.object_id FROM sys.objects o WHERE o.object_id = OBJECT_ID(@obj) AND o.type IN ('U', 'V'));
DECLARE @objsql nvarchar(600) = QUOTENAME(OBJECT_SCHEMA_NAME(@oid)) + N'.' + QUOTENAME(OBJECT_NAME(@oid));

IF @oid IS NULL
    SET @err = N'Source table ' + @obj + N' not found. Check the delta twin OBJECT_NAME and SourceConfig.';

-- Window column.
DECLARE @wtype sysname, @wsql nvarchar(300), @wkind varchar(4) = '';
IF @wcol <> N''
    SELECT @wtype = TYPE_NAME(c.system_type_id), @wsql = QUOTENAME(c.name)
    FROM sys.columns c WHERE c.object_id = @oid AND c.name = @wcol;
SET @wkind = CASE WHEN @wtype IN ('date', 'datetime', 'datetime2', 'smalldatetime') THEN 'date'
                  WHEN @wtype IN ('tinyint', 'smallint', 'int', 'bigint') THEN 'int' ELSE '' END;
IF @err = N'' AND @wcol = N'' AND (@ws <> N'' OR @we <> N'')
    SET @err = N'A window bound is set but window_column is empty.';
IF @err = N'' AND @wcol <> N'' AND @wsql IS NULL
    SET @err = N'Window column ' + @wcol + N' not found in ' + @obj + N'.';
IF @err = N'' AND @wcol <> N'' AND @wkind = ''
    SET @err = N'Window column ' + @wcol + N' is ' + @wtype + N'; only date, datetime, datetime2, smalldatetime and integer types are supported.';

-- Bounds: S = start (>=), E = end (<).
DECLARE @b TABLE (k char(1), v nvarchar(64), d datetime2(3), i bigint);
INSERT @b (k, v) SELECT 'S', @ws WHERE @ws <> N'' UNION ALL SELECT 'E', @we WHERE @we <> N'';
UPDATE @b SET
    d = CASE WHEN v LIKE N'[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'
               OR (v LIKE N'[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]%'
                   AND SUBSTRING(v, 20, 64) NOT LIKE N'%[^0-9.]%')
             THEN TRY_CONVERT(datetime2(3), v) END,
    i = TRY_CONVERT(bigint, v);
IF @err = N'' AND @wkind = 'date' AND EXISTS (SELECT 1 FROM @b WHERE d IS NULL)
    SET @err = N'Window bound ' + (SELECT TOP 1 v FROM @b WHERE d IS NULL) + N' is not yyyy-mm-dd or yyyy-mm-ddThh:mi:ss[.fff] (no offset or Z).';
IF @err = N'' AND @wtype = 'date' AND EXISTS (SELECT 1 FROM @b WHERE CAST(d AS time) <> '00:00')
    SET @err = N'Window column ' + @wcol + N' is a date; bounds must not have a time part.';
IF @err = N'' AND @wtype = 'smalldatetime' AND EXISTS (SELECT 1 FROM @b WHERE DATEPART(second, d) <> 0 OR DATEPART(millisecond, d) <> 0)
    SET @err = N'Window column ' + @wcol + N' is smalldatetime; bounds must be whole minutes.';
IF @err = N'' AND @wkind = 'int' AND EXISTS (SELECT 1 FROM @b WHERE i IS NULL)
    SET @err = N'Window bound ' + (SELECT TOP 1 v FROM @b WHERE i IS NULL) + N' is not an integer.';
-- Default end for date windows: server clock, floored (to the day for date, else to the minute) so it never moves later.
IF @err = N'' AND @wkind = 'date' AND NOT EXISTS (SELECT 1 FROM @b WHERE k = 'E')
    INSERT @b (k, v, d) SELECT 'E', N'server clock',
        CASE WHEN @wtype = 'date' THEN CAST(CAST(SYSDATETIME() AS date) AS datetime2(3))
             ELSE CAST(DATEADD(minute, DATEDIFF(minute, 0, SYSDATETIME()), 0) AS datetime2(3)) END;
IF @err = N'' AND EXISTS (SELECT 1 FROM @b s JOIN @b e ON s.k = 'S' AND e.k = 'E'
                          WHERE (@wkind = 'date' AND s.d >= e.d) OR (@wkind = 'int' AND s.i >= e.i))
    SET @err = N'Window start must be before window end.';

DECLARE @wpred nvarchar(max) = N'';
IF @err = N''
    SELECT @wpred = @wpred + N' AND ' + @wsql + CASE k WHEN 'S' THEN N' >= ' ELSE N' < ' END
        + CASE @wkind WHEN 'date' THEN N'CONVERT(' + @wtype + N', ''' + CONVERT(nvarchar(23), d, 126) + N''', 126)'
                      ELSE CAST(i AS nvarchar(20)) END
    FROM @b;

-- Partition column: an indexed integer, for parallel key-range batches.
DECLARE @ptype sysname, @psql nvarchar(300), @pnull bit, @pidx bit;
IF @pcol <> N''
    SELECT @ptype = TYPE_NAME(c.system_type_id), @psql = QUOTENAME(c.name), @pnull = c.is_nullable,
           @pidx = CASE WHEN EXISTS (SELECT 1 FROM sys.index_columns ic
                                     WHERE ic.object_id = c.object_id AND ic.column_id = c.column_id AND ic.key_ordinal = 1)
                        THEN 1 ELSE 0 END
    FROM sys.columns c WHERE c.object_id = @oid AND c.name = @pcol;
IF @err = N'' AND @pcol <> N'' AND @psql IS NULL
    SET @err = N'Partition column ' + @pcol + N' not found in ' + @obj + N'.';
IF @err = N'' AND @pcol <> N'' AND @ptype NOT IN ('tinyint', 'smallint', 'int', 'bigint')
    SET @err = N'Partition column ' + @pcol + N' is ' + @ptype + N'; it must be an integer type.';
IF @err = N'' AND @pcol <> N'' AND @pidx = 0
    SET @err = N'Partition column ' + @pcol + N' is not the leading column of an index; leave partition_column empty.';
IF @err = N'' AND @n < 1000
    SET @err = N'p_Rows_Per_File must be at least 1000.';

-- SELECT list: raw columns in column order, like the delta's SELECT *, so the JSON sink writes the same text as
-- the delta feed. Only types ADF cannot read are converted.
DECLARE @list nvarchar(max) = STUFF((
    SELECT N', ' + CASE
        WHEN c.system_type_id = 240 THEN x.q + N'.ToString()'                                   -- hierarchyid, geography, geometry
        WHEN x.t = 'sql_variant' THEN N'CONVERT(nvarchar(max), ' + x.q + N')'
        ELSE x.q END + N' AS ' + x.q
    FROM sys.columns c CROSS APPLY (SELECT TYPE_NAME(c.system_type_id) AS t, QUOTENAME(c.name) AS q) x
    WHERE c.object_id = @oid ORDER BY c.column_id
    FOR XML PATH(''), TYPE).value('.', 'nvarchar(max)'), 1, 2, N'');

DECLARE @src nvarchar(max) = N'SELECT ' + @list + N' FROM ' + @objsql + N' WITH (NOLOCK) WHERE 1 = 1' + @wpred;

-- Batch ranges: half-open on the partition key, first open below, last open above, NULL keys in their own batch
-- (only when NULL keys exist: an empty JSON file must never be the first file loaded, which creates BRONZE).
-- The batch count is checked on the ranges actually produced (#r), so batches + batch 0 never exceed the 5000-row
-- Lookup cap, which would otherwise drop batches silently.
DECLARE @pq nvarchar(600) = REPLACE(@psql, N'''', N'''''');   -- key name inside a literal of the generated query
DECLARE @ranges nvarchar(max) = CASE WHEN @pcol = N''
    THEN N'SELECT 1 AS BATCH_NO, CAST(N'''' AS nvarchar(400)) AS BATCH_FILTER;'
    ELSE N'SET NOCOUNT ON;
DECLARE @step bigint = ' + CAST(@n AS nvarchar(10)) + N';
WITH t AS (SELECT ' + @psql + N' AS k, ROW_NUMBER() OVER (ORDER BY ' + @psql + N') AS rn FROM ' + @objsql
        + N' WITH (NOLOCK) WHERE ' + @psql + N' IS NOT NULL' + @wpred + N'),
b AS (SELECT DISTINCT k AS lo FROM t WHERE (rn - 1) % @step = 0),
r AS (SELECT lo, LEAD(lo) OVER (ORDER BY lo) AS hi, ROW_NUMBER() OVER (ORDER BY lo) AS n FROM b)
SELECT lo, hi, n INTO #r FROM r;
IF (SELECT COUNT(*) FROM #r) > 4999 THROW 50001, N''More than 4999 batches (one file each): raise p_Rows_Per_File.'', 1;
SELECT n AS BATCH_NO, N'' AND ' + @pq + N' IS NOT NULL''
     + CASE WHEN n > 1 THEN N'' AND ' + @pq + N' >= '' + CAST(lo AS nvarchar(20)) ELSE N'''' END
     + CASE WHEN hi IS NOT NULL THEN N'' AND ' + @pq + N' < '' + CAST(hi AS nvarchar(20)) ELSE N'''' END AS BATCH_FILTER
FROM #r' + CASE WHEN @pnull = 1 THEN N'
UNION ALL SELECT 0, N'' AND ' + @pq + N' IS NULL'' WHERE EXISTS (SELECT 1 FROM ' + @objsql + N' WITH (NOLOCK) WHERE '
        + @psql + N' IS NULL' + @wpred + N')' ELSE N'' END + N';'
    END;

-- Row estimate (whole table, from metadata). The JSON pipeline does not use it as a file-count guard: without a
-- partition column it writes one file, and with one the #r check above applies.
DECLARE @est bigint = (SELECT SUM(p.rows) FROM sys.partitions p WHERE p.object_id = @oid AND p.index_id IN (0, 1));

SELECT @err AS ERROR_MESSAGE,
       COALESCE(@est, 0) AS ROWS_ESTIMATE,
       CASE WHEN @err = N'' THEN @src END AS SOURCE_QUERY,
       CASE WHEN @err = N'' THEN @ranges END AS RANGES_SQL,
       CASE WHEN @err = N'' THEN @wpred END AS WINDOW_FILTER;

