EXECUTE IMMEDIATE $$
-- 'Begin prime' Lookup: lock, abandon the initial row's old plans, delta OFF, truncate BRONZE.
-- Runs only after 'Check pair' and 'Get source columns' passed. Tokens {{...}} come from 'Check pair'.
-- Test mode (@{activity('Check pair').output.firstRow.TEST_MODE} = True): the delta twin is never touched; only the test table is truncated.
DECLARE
    v_status VARCHAR DEFAULT 'ERROR';
    msg      VARCHAR DEFAULT '';
    cnt      NUMBER DEFAULT 0;
    v_maxplan NUMBER DEFAULT 0;
    v_pid    NUMBER;
    v_pmsg   VARCHAR DEFAULT 'Abandoned by data prime run @{formatDateTime(pipeline().TriggerTime, 'yyyyMMddHHmmss')}';
    v_tbl    VARCHAR DEFAULT '@{replace(activity('Check pair').output.firstRow.BRONZE_TABLE, '''', '''''')}';
    res      RESULTSET;
BEGIN
    -- Lock (atomic): the initial row's ACTIVE_FLAG. p_Force takes over a lock left by a cancelled run.
    UPDATE EDP_DEV.CONTROL.EXTRACT_META SET ACTIVE_FLAG = TRUE
    WHERE EXTRACT_META_ID = @{activity('Check pair').output.firstRow.INITIAL_META_ID} AND (COALESCE(ACTIVE_FLAG, FALSE) = FALSE OR @{pipeline().parameters.p_Force});
    IF (SQLROWCOUNT = 0) THEN
        msg := 'Initial row @{activity('Check pair').output.firstRow.INITIAL_META_ID} is ACTIVE: another prime is running, or one was cancelled. '
            || 'Check ADF Monitor, then re-run with p_Force = true.';
    ELSE
        BEGIN
            -- Old open plans of the initial row belong to earlier primes. Close them, or ATILDA keeps re-processing them
            -- (PR_CREATE_EXTRACT_ARTIFACTS touches every open plan of the row). EXTRACT_RUN_PLAN_VW counts a plan as open
            -- while its latest extract_run_plan_status is PLANNED; etlplan_status alone does not close it.
            LET plans RESULTSET := (SELECT EXTRACT_RUN_PLAN_ID FROM EDP_DEV.CONTROL.EXTRACT_RUN_PLAN_STATUS_VW
                                    WHERE EXTRACT_META_ID = @{activity('Check pair').output.firstRow.INITIAL_META_ID} AND EXTRACT_RUN_PLAN_STATUS = 'PLANNED');
            LET c_plans CURSOR FOR plans;
            FOR rec IN c_plans DO
                v_pid := rec.EXTRACT_RUN_PLAN_ID;
                CALL EDP_DEV.CONTROL.PR_LOG_EXTRACT_RUN_PLAN(:v_pid, 'etlplan_status', 'ABANDONED', :v_pmsg);
                CALL EDP_DEV.CONTROL.PR_LOG_EXTRACT_RUN_PLAN(:v_pid, 'extract_run_plan_status', 'ABANDONED', :v_pmsg);
            END FOR;

            -- Delta OFF, then re-check: a delta run may have planned since 'Check pair'. Skipped in test mode.
            IF (NOT @{activity('Check pair').output.firstRow.TEST_MODE}) THEN
                UPDATE EDP_DEV.CONTROL.EXTRACT_META SET ACTIVE_FLAG = FALSE WHERE EXTRACT_META_ID = @{activity('Check pair').output.firstRow.DELTA_META_ID};
                SELECT COUNT(*), COALESCE(MAX(EXTRACT_RUN_PLAN_ID), 0) INTO :cnt, :v_maxplan
                FROM EDP_DEV.CONTROL.EXTRACT_RUN_PLAN_STATUS_VW WHERE EXTRACT_META_ID = @{activity('Check pair').output.firstRow.DELTA_META_ID};
                SELECT COUNT(*) INTO :cnt FROM EDP_DEV.CONTROL.EXTRACT_RUN_PLAN_STATUS_VW
                WHERE EXTRACT_META_ID = @{activity('Check pair').output.firstRow.DELTA_META_ID} AND EXTRACT_RUN_PLAN_STATUS = 'PLANNED';
                -- v_maxplan: the delta's highest plan id once it is OFF; End fails on any later plan (late_delta).
            END IF;
            IF (cnt > 0) THEN
                UPDATE EDP_DEV.CONTROL.EXTRACT_META SET ACTIVE_FLAG = @{activity('Check pair').output.firstRow.DELTA_ACTIVE} WHERE EXTRACT_META_ID = @{activity('Check pair').output.firstRow.DELTA_META_ID};
                UPDATE EDP_DEV.CONTROL.EXTRACT_META SET ACTIVE_FLAG = FALSE WHERE EXTRACT_META_ID = @{activity('Check pair').output.firstRow.INITIAL_META_ID};
                msg := 'Delta twin @{activity('Check pair').output.firstRow.DELTA_META_ID} planned ' || cnt || ' run(s) while the prime was starting. '
                    || 'Nothing was truncated. Let it finish, then re-run.';
            ELSE
                TRUNCATE TABLE IF EXISTS IDENTIFIER(:v_tbl);
                v_status := 'OK';
                msg := 'Locked and cleared ' || v_tbl
                    || IFF(@{activity('Check pair').output.firstRow.TEST_MODE}, ' (test mode: delta twin @{activity('Check pair').output.firstRow.DELTA_META_ID} untouched).', '; delta twin @{activity('Check pair').output.firstRow.DELTA_META_ID} is OFF.');
            END IF;
        EXCEPTION
            -- TRUNCATE is the last statement that can fail, so on any error BRONZE is untouched: restore both flags.
            WHEN OTHER THEN
                v_status := 'ERROR';
                msg := 'Begin failed (' || SQLERRM || '). Nothing was truncated; lock released, delta twin restored.';
                IF (NOT @{activity('Check pair').output.firstRow.TEST_MODE}) THEN
                    UPDATE EDP_DEV.CONTROL.EXTRACT_META SET ACTIVE_FLAG = @{activity('Check pair').output.firstRow.DELTA_ACTIVE} WHERE EXTRACT_META_ID = @{activity('Check pair').output.firstRow.DELTA_META_ID};
                END IF;
                UPDATE EDP_DEV.CONTROL.EXTRACT_META SET ACTIVE_FLAG = FALSE WHERE EXTRACT_META_ID = @{activity('Check pair').output.firstRow.INITIAL_META_ID};
        END;
    END IF;
    res := (SELECT :v_status AS STATUS, :msg AS MESSAGE, :v_maxplan AS DELTA_MAX_PLAN);
    RETURN TABLE(res);
END;
$$

EXECUTE IMMEDIATE $$
-- 'End prime' Lookup: reconcile this run, check the delta twin's watermark, release the lock, and turn the delta
-- twin ON only when the reconcile passed, p_Enable_Delta is true, BRONZE is not empty and the watermark is usable.
-- Tokens {{...}} come from 'Check pair' and from the batch rows returned by PL_ATILDA_DATA_PRIME_IN.
-- Test mode (@{activity('Check pair').output.firstRow.TEST_MODE} = True): reconcile only; the delta twin is never touched.
DECLARE
    v_status    VARCHAR DEFAULT 'ERROR';
    msg         VARCHAR DEFAULT '';
    v_tag       VARCHAR DEFAULT '_part_@{formatDateTime(pipeline().TriggerTime, 'yyyyMMddHHmmss')}_';
    v_rx        VARCHAR DEFAULT '_part_@{formatDateTime(pipeline().TriggerTime, 'yyyyMMddHHmmss')}_b([0-9]+)_';
    v_tbl       VARCHAR DEFAULT '@{replace(activity('Check pair').output.firstRow.BRONZE_TABLE, '''', '''''')}';
    v_wmq       VARCHAR DEFAULT '@{coalesce(activity('Check pair').output.firstRow.WM_QUERY, '')}';
    v_dupq      VARCHAR DEFAULT '@{coalesce(activity('Check pair').output.firstRow.DUP_QUERY, '')}';
    rows_copied NUMBER DEFAULT 0;
    bronze_rows NUMBER DEFAULT 0;
    other_rows  NUMBER DEFAULT 0;
    open_plans  NUMBER DEFAULT 0;
    mismatch    VARCHAR DEFAULT '';
    dup_keys    NUMBER DEFAULT 0;
    tbl_exists  NUMBER DEFAULT 0;
    late_delta  NUMBER DEFAULT 0;
    wm_ok       BOOLEAN DEFAULT FALSE;
    wm_msg      VARCHAR DEFAULT '';
    outv        VARCHAR;
    tok         VARCHAR;
    restored    BOOLEAN DEFAULT FALSE;
    res         RESULTSET;
BEGIN
    BEGIN
        -- Rows extracted, per batch, as returned by PL_ATILDA_DATA_PRIME_IN: [{"b": "<batch>", "rows": <n>}, ...]
        SELECT COALESCE(SUM(f.value:"rows"::NUMBER), 0) INTO :rows_copied
        FROM TABLE(FLATTEN(INPUT => PARSE_JSON('@{string(activity('Data in').output.pipelineReturnValue.batch_rows)}'))) f;

        SELECT COUNT(*) INTO :open_plans FROM EDP_DEV.CONTROL.EXTRACT_RUN_PLAN_STATUS_VW
        WHERE EXTRACT_META_ID = @{activity('Check pair').output.firstRow.INITIAL_META_ID} AND CONTAINS(FILE_NAME, :v_tag) AND EXTRACT_RUN_PLAN_STATUS <> 'COMPLETED';

        -- Live mode: a delta plan created after 'Check pair' (a J4 run that read the flags before begin turned the
        -- delta OFF) could load into BRONZE after this check. Refuse to pass; the delta stays OFF.
        IF (NOT @{activity('Check pair').output.firstRow.TEST_MODE}) THEN
            SELECT COUNT(*) INTO :late_delta FROM EDP_DEV.CONTROL.EXTRACT_RUN_PLAN_STATUS_VW
            WHERE EXTRACT_META_ID = @{activity('Check pair').output.firstRow.DELTA_META_ID} AND EXTRACT_RUN_PLAN_ID > @{activity('Begin prime').output.firstRow.DELTA_MAX_PLAN};
        END IF;

        SELECT COUNT(*) INTO :tbl_exists FROM EDP_DEV.INFORMATION_SCHEMA.TABLES
        WHERE TABLE_SCHEMA = '@{replace(activity('Check pair').output.firstRow.TARGET_SCHEMA, '''', '''''')}' AND TABLE_NAME = '@{replace(activity('Check pair').output.firstRow.STAGE_TABLE, '''', '''''')}';

        IF (tbl_exists = 1) THEN
            -- other_rows: BRONZE was truncated at begin, so any row not from this run is contamination
            -- (for example a load still running in Snowflake from a cancelled run).
            SELECT COUNT_IF(CONTAINS(ETL_FILE_NAME, :v_tag)), COUNT_IF(NOT COALESCE(CONTAINS(ETL_FILE_NAME, :v_tag), FALSE))
            INTO :bronze_rows, :other_rows FROM IDENTIFIER(:v_tbl);

            -- Per batch: rows loaded vs rows extracted. A batch of 0 rows wrote no file.
            SELECT COALESCE(LISTAGG('b' || COALESCE(b.k, t.k) || ' extracted ' || COALESCE(b.n, 0)
                                    || ' loaded ' || COALESCE(t.n, 0), '; '), '')
            INTO :mismatch
            FROM (SELECT f.value:"b"::VARCHAR AS k, f.value:"rows"::NUMBER AS n
                  FROM TABLE(FLATTEN(INPUT => PARSE_JSON('@{string(activity('Data in').output.pipelineReturnValue.batch_rows)}'))) f) b
            FULL OUTER JOIN
                 (SELECT REGEXP_SUBSTR(COLLATE(ETL_FILE_NAME, ''), :v_rx, 1, 1, 'e', 1) AS k, COUNT(*) AS n
                  FROM IDENTIFIER(:v_tbl) WHERE CONTAINS(ETL_FILE_NAME, :v_tag) GROUP BY 1) t
              ON b.k = t.k
            WHERE COALESCE(b.n, 0) <> COALESCE(t.n, 0);

            -- Duplicate keys (PRIMARY_KEYS, NULL-safe GROUP BY) over the whole table.
            IF (v_dupq <> '') THEN
                LET drs RESULTSET := (EXECUTE IMMEDIATE :v_dupq);
                LET dc CURSOR FOR drs;
                OPEN dc;
                FETCH dc INTO dup_keys;
                CLOSE dc;
            END IF;
        END IF;

        -- Delta twin watermark: run its own SQL_SNIPPET as ATILDA does. Empty BRONZE or an unparseable watermark
        -- yields 1900-01-01, which would make the delta pull the whole table.
        IF (v_wmq = '') THEN
            wm_ok := TRUE;
            wm_msg := 'no SQL_SNIPPET (full pull feed)';
        ELSE
            BEGIN
                LET wrs RESULTSET := (EXECUTE IMMEDIATE :v_wmq);
                LET wc CURSOR FOR wrs;
                OPEN wc;
                FETCH wc INTO outv;
                CLOSE wc;
                tok := REGEXP_SUBSTR(COLLATE(outv, ''), '[0-9]{4}-[0-9]{2}-[0-9]{2}([ T][0-9]{2}:[0-9]{2}(:[0-9]{2}([.][0-9]+)?)?)?');
                wm_ok := (tok IS NULL OR COALESCE(TRY_TO_TIMESTAMP_NTZ(REPLACE(tok, 'T', ' ')) >= '1901-01-01'::TIMESTAMP_NTZ, FALSE));
                wm_msg := 'watermark ' || COALESCE(tok, 'none in snippet output');
            EXCEPTION
                WHEN OTHER THEN
                    wm_ok := FALSE;
                    wm_msg := 'snippet failed: ' || SQLERRM;
            END;
        END IF;

        UPDATE EDP_DEV.CONTROL.EXTRACT_META SET ACTIVE_FLAG = FALSE WHERE EXTRACT_META_ID = @{activity('Check pair').output.firstRow.INITIAL_META_ID};
        IF (open_plans = 0 AND bronze_rows = rows_copied AND other_rows = 0 AND mismatch = '' AND dup_keys = 0
            AND late_delta = 0) THEN
            v_status := 'OK';
            IF (@{activity('Check pair').output.firstRow.TEST_MODE}) THEN
                msg := 'Test prime: ' || bronze_rows || ' rows in ' || v_tbl || '. Delta twin @{activity('Check pair').output.firstRow.DELTA_META_ID} untouched.';
            ELSEIF (@{activity('Check pair').output.firstRow.ENABLE_DELTA} AND bronze_rows > 0 AND wm_ok) THEN
                UPDATE EDP_DEV.CONTROL.EXTRACT_META SET ACTIVE_FLAG = TRUE WHERE EXTRACT_META_ID = @{activity('Check pair').output.firstRow.DELTA_META_ID};
                restored := TRUE;
                msg := 'Primed ' || bronze_rows || ' rows. Delta twin @{activity('Check pair').output.firstRow.DELTA_META_ID} is ON (' || wm_msg || ').';
            ELSE
                msg := 'Primed ' || bronze_rows || ' rows. Delta twin @{activity('Check pair').output.firstRow.DELTA_META_ID} left OFF: '
                    || CASE WHEN NOT @{activity('Check pair').output.firstRow.ENABLE_DELTA} THEN 'p_Enable_Delta is false.'
                            WHEN bronze_rows = 0 THEN 'BRONZE is empty, the delta would pull the whole table.'
                            ELSE 'its watermark is not usable (' || wm_msg || ').' END;
            END IF;
        ELSE
            msg := 'Reconcile failed: open_plans=' || open_plans || ', rows_copied=' || rows_copied
                || ', bronze_rows=' || bronze_rows || ', other_rows=' || other_rows || ', dup_keys=' || dup_keys
                || IFF(late_delta = 0, '', ', delta twin @{activity('Check pair').output.firstRow.DELTA_META_ID} planned ' || late_delta || ' run(s) during the prime')
                || IFF(mismatch = '', '', ', batches: ' || mismatch)
                || '. Lock released; delta twin left OFF. Fix the cause and re-run.';
        END IF;
    EXCEPTION
        WHEN OTHER THEN
            v_status := 'ERROR';
            msg := 'End failed (' || SQLERRM || '). Lock released; delta twin left OFF.';
            UPDATE EDP_DEV.CONTROL.EXTRACT_META SET ACTIVE_FLAG = FALSE WHERE EXTRACT_META_ID = @{activity('Check pair').output.firstRow.INITIAL_META_ID};
    END;
    res := (SELECT :v_status AS STATUS, :msg AS MESSAGE, :rows_copied AS ROWS_COPIED, :bronze_rows AS BRONZE_ROWS,
                   :other_rows AS OTHER_ROWS, :open_plans AS OPEN_PLANS, :mismatch AS BATCH_MISMATCH,
                   :dup_keys AS DUP_KEYS, :restored AS DELTA_RESTORED);
    RETURN TABLE(res);
END;
$$
